export interface CustomerRecord {
  id: number;
  name: string;
  nameKn: string;
  shop: string;
  ph: string;
  adh: string;
  adhv?: string;
  gstin?: string;
  lm: string;
  state: string;
  district: string;
  taluka: string;
  village: string;
  villageKn?: string;
  villageKey?: string;
  pincode: string;
  route: string;
  beat: string;
  status: "active" | "inactive" | "unbilled";
  lastBillDate?: string | null;
  lastBillDays?: number | null;
  createdAt: string;
}

export interface RouteRecord {
  name: string;
  beatDays: string[];
  crmName?: string;
  villages: {
    name: string;
    key: string;
    customerCount: number;
  }[];
  totalCustomers: number;
}

